5	namespace App\Filament\Resources\Fabrics\Schemas;
6	
7	use App\Models\Fabric;
8	use App\Models\FabricCategory;
9	use App\Pim\Filament\Schemas\Category1Select;
10	use AtrioTeam\DigitalHub\Pim\Filament\Schemas\NameAndId;
11	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
12	use AtrioTeam\DigitalHub\Tags\Filament\TagPicker;
13	use Filament\Forms\Components\TextInput;
14	use Filament\Infolists\Components\TextEntry;
15	use Filament\Resources\Pages\Page;
16	use Filament\Schemas\Components\Section;
17	use Filament\Schemas\Schema;
18	use Illuminate\Database\Eloquent\Builder;
19	
20	class FabricForm
21	{
22	    public static function configure(Schema $schema): Schema
23	    {
24	        return $schema
25	            ->components([
26	                // solo informativo: per i tessuti la destinazione è stabilita
27	                // dalla categoria parent (risorsa nidificata)
28	                Category1Select::section(
29	                    TextEntry::make('category1_info')
30	                        ->hiddenLabel()
31	                        ->state(function (Page $livewire): string {
32	                            $category = $livewire->getParentRecord();
33	
34	                            return $category instanceof FabricCategory
35	                                ? ($category->category1->name ?? '—')
36	                                : '—';
37	                        }),
38	                ),
39	                // fabric_category_id valorizzato dalla relazione parent (risorsa nidificata)
40	                NameAndId::make($schema),
41	                // campi anagrafici/commerciali importati dal listino CAPITAL
42	                Section::make(__('fabric.capital_data'))
43	                    ->columns(3)
44	                    ->schema([
45	                        TextInput::make('code')->label(__('fabric.code'))->maxLength(255),
46	                        TextInput::make('color')->label(__('fabric.color'))->maxLength(255),
47	                        TextInput::make('price_category')->label(__('fabric.price_category'))->maxLength(255),
48	                        TextInput::make('sample_size')->label(__('fabric.sample_size'))->maxLength(255),
49	                        TextInput::make('unit_price')->label(__('fabric.unit_price'))->numeric(),
50	                        TextInput::make('note')->label(__('fabric.note'))->maxLength(255),
51	                        TextInput::make('category_code')->label(__('fabric.category_code'))->maxLength(255),
52	                        TextInput::make('sku')->label(__('fabric.sku'))->maxLength(255),
53	                        TextInput::make('description')->label(__('fabric.description'))->maxLength(255)->columnSpanFull(),
54	                    ]),
55	                // solo i tag dei gruppi (fabric, entity) — vincolo rigido — della
56	                // Destinazione del tessuto (Category1 della categoria parent);
57	                // i gruppi senza Destinazione valgono per tutte
58	                TagPicker::make(
59	                    (new Fabric())->getMorphClass(),
60	                    TagTarget::Entity,
61	                    function (Builder $query, Page $livewire): Builder {
62	                        $category = $livewire->getParentRecord();
63	                        $category1Id = $category instanceof FabricCategory ? $category->category_1_id : null;
64	
65	                        return $query->where(fn (Builder $q): Builder => $q
66	                            ->whereNull('category_1_id')
67	                            ->when($category1Id !== null, fn (Builder $q2): Builder => $q2->orWhere('category_1_id', $category1Id)));
68	                    },
69	                ),
70	            ]);
71	    }
72	}
